/**
 * This script runs before the block entry module. The block and shell use
 * different origins, so the iframe must report its own uncaught errors.
 */
export const RUNTIME_ERROR_CLIENT_SOURCE = `
const MESSAGE_TYPE = "notion-custom-blocks-dev-shell:runtime-error"

function report(error, fallback, location) {
	const message =
		typeof error === "object" &&
		error !== null &&
		typeof error.message === "string"
			? error.message
			: typeof error === "string"
				? error
				: fallback
	const stack =
		typeof error === "object" &&
		error !== null &&
		typeof error.stack === "string"
			? error.stack
			: undefined
	const filename =
		location !== undefined && typeof location.filename === "string"
			? location.filename
			: undefined
	const lineno =
		location !== undefined && typeof location.lineno === "number"
			? location.lineno
			: undefined
	const colno =
		location !== undefined && typeof location.colno === "number"
			? location.colno
			: undefined
	window.parent.postMessage({
		type: MESSAGE_TYPE,
		error: { message, stack, filename, lineno, colno },
	}, "*")
}

window.addEventListener("error", event => {
	report(event.error, event.message || "Uncaught error", {
		filename: event.filename,
		lineno: event.lineno,
		colno: event.colno,
	})
})

window.addEventListener("unhandledrejection", event => {
	report(event.reason, "Unhandled promise rejection")
})
`;
